['Light','Dark'].forEach(function(a){var p=H.page('Proto macOS '+a);p.layers.filter(function(s){return s.name.indexOf('Screen/macos/')===0;}).forEach(function(s){var id=s.name.split('/').pop(), all=[];function walk(l){all.push(l);(l.layers||[]).forEach(walk);}walk(s);var sb=s.layers.find(function(l){return l.name==='sidebar';}),tb=all.find(function(l){return l.name==='toolbar';});var r={id:id,appearance:a,frame:s.id,w:s.frame.width,h:s.frame.height,sidebar:sb?sb.frame.width:null,toolbar:tb?tb.frame.height:null};if(id==='settings-appearance')r.forms=all.filter(function(l){return l.name.indexOf('form:')===0;}).map(function(l){return {name:l.name,x:l.frame.x,h:l.frame.height,children:l.layers.map(function(c){return {name:c.name,text:c.text,x:c.frame.x,w:c.frame.width,h:c.frame.height};})};});if(id==='signin')r.controls=all.filter(function(l){return l.parent.name==='authentication';}).map(function(l){return {name:l.name,h:l.frame.height,y:l.frame.y};});if(id==='conversation--menu'){r.menu=all.filter(function(l){return l.parent.id===s.id&&/menu/.test(l.name);}).map(function(l){return {name:l.name,x:l.frame.x,w:l.frame.width};});r.export=all.filter(function(l){return /export/i.test(l.name);}).map(function(l){return {name:l.name,text:l.text,cp:l.text?l.text.codePointAt(0):null};});}console.log(JSON.stringify(r));});});